We accept the following facts without proof: 
\begin{itemize}
\item  $X^p - Z^{p-1}X = (X)(X-Z)\cdots(X-Z(p-1))$  in any polynomial field extension of characteristic  $P$ , where  $X$  and  $Z$  are polynomial. This is a consequence of some easy factoring. 

\item If  $P(X, Y, Z)$  has all nonzero monomial terms of the form  $X^{p^i}Y^{p^j}Z^{p^k}$  then  $P(X, Y, Z) + P(W, Y, Z) = P(X + W, Y, Z)$  and similar, where  $P$  is a multivariate polynomial. This is a consequence of the Frobenius Endomorphism. 

\item If \[ P(X, Y, Z) = \sum_{i = 0}^{\infty}\sum_{j = 0}^{\infty}\sum_{k = 0}^{\infty} a_{ijk} X^{p^i}Y^{p^j}Z^{p^k} \] then \[ P(X, Y, Z)^p \equiv \sum_{i = 0}^{\infty}\sum_{j = 0}^{\infty}\sum_{k = 0}^{\infty} a_{ijk} X^{p^{i+1}}Y^{p^{j+1}}Z^{p^{k+1}} \] This is also a consequence of the Frobenius Endomorphism. 
\end{itemize}

We will explicitly find the polynomials, which are  $x + ky + \ell z$ , for  $0 \le k \le p-1$  and  $0 \le \ell \le p-1$ ,  $y - kz$ , where  $0 \le k \le p-1$ , and  $z$ . 

Observe that \[ \prod_{k = 0}^{p-1} \prod_{\ell = 0}^{p-1} (x + ky + \ell z) = \prod_{k = 0}^{p-1} ((x + ky)^p - (x + ky)z^{p-1} \] due to the first fact. Next, let  $P(x, z) = x^p - xz^{p-1}$  and realize that the remaining product is 

\begin{align*}
\prod_{k=0}^{p-1} P(x + ky, z) &= \prod_{k = 0}^{p-1} P(x, z) - kP(y, z) 
&= P(x, z)^{p} - P(x, z)P(y, z)^{p-1} 
\end{align*}

We next multiply this by  $z\prod_{k = 0}^{p-1}(y - kz)$ , which is  $zP(y, z)$ . The product of this and the previous is 
\begin{align*}
zP(x, z)^{p}P(y, z) - zP(x, z)P(y, z)^p &= z(x^p - xz^{p-1})^p(y^p - yz^{p-1}) - z(x^p - xz^{p-1})(y^p - yz^{p-1})^p 
&= z(x^{p^2} - x^pz^{p^2-p})(y^p - yz^{p-1}) - z(x^p - xz^{p-1})(y^{p^2} - yz^{p^2 - p}) 
&= -\begin{bmatrix}x & y & z x^p & y^p & z^p  x^{p^2} & y^{p^2} & z^{p^2} \end{bmatrix}
\end{align*}

Let  $z_k = (a_k / b_k)^{1/n}$ . We want to show
\begin{align*}
 (1 + z_1...z_n)^n &\le (1+z_1^n)...(1+z_n^n). 
\sum_{k=0}^n \binom{n}{k}(z_1...z_n)^k &\le \sum_{S\subseteq [n]} (z_{S_1}...z_{S_\ell})^n 
\sum_{k=0}^n \binom{n}{k}(z_1...z_n)^k &\le \sum_{k=0}^n \sum_{S\subseteq [n], |S| = k}  ( z_{S_1}... z_{S_k} )^n.
\end{align*}
By AM-GM,
\begin{align*}
\sum_{S\subseteq [n], |S| = k}  ( z_{S_1}... z_{S_k} )^n &\ge \binom{n}{k} \left(\prod_{S\subseteq [n], |S| = k}  ( z_{S_1}... z_{S_k} )^n \right)^{\frac{1}{\binom{n}{k}}}.
\end{align*}
And in the RHS product, any given  $z_i^n$  appears  $\binom{n-1}{k-1}$  times. So in total,  $z_i$ 's exponent is  $n\binom{n-1}{k-1} / \binom{n}{k} = k$ . So 
\begin{align*}
\sum_{S\subseteq [n], |S| = k}  ( z_{S_1}... z_{S_k} )^n &\ge \binom{n}{k} (z_1...z_n)^k,
\end{align*}
which is what we wanted to show.

