\begin{align*}
    2017a_{63}
    &= 63!\cdot\sum_{i=2}^{63}(-1)^{i+1}\binom{2017}{i}
    &= 63!\cdot\sum_{i=2}^{63}(-1)^{i+1}\left(\binom{2016}{i-1}+\binom{2016}{i}\right)
    &= 63!\left(\binom{2016}{1}+\binom{2016}{63}\right)
    &= \boxed{63!\left(2016+\binom{2016}{63}\right)}.
\end{align*}

