We use Lagrange interpolation to find the explicit formula for  $p$ . We define for $n=0,1,2,\cdots, 1008$ , the function  $$ p_n(x) = \prod_{0\le k\le 1008;\; k\neq n}\frac{x-(2k+1)}{(2n+1)-(2k+1)} = \frac1{2^{1008}}\prod_{0\le k\le 1008;\; k\neq n}\frac{x-2k-1}{n-k} $$  which is  $0$  at each  $2k+1$  except at  $2n+1$  where it is  $1$ . Then we have  $$ p(x) = \sum_{n=0}^{1008}F_{2n+1}p_n(x) $$  Next we compute
\begin{align*}
p_n(2019) &= \frac1{2^{1008}}\prod_{0\le k\le 1008;\; k\neq n}\frac{2019-2k-1}{n-k} 
&= \prod_{0\le k\le 1008;\;k\neq n}\frac{1009-k}{n-k} 
&= \frac{1009!}{1009-n}\prod_{k=0}^{n-1}\frac1{n-k}\prod_{k=n+1}^{1008}\frac1{n-k} 
&= \frac{(-1)^n1009!}{(1009-n)n!(1008-n)!} 
&= (-1)^n\binom{1009}n
\end{align*}
Thus  $$ p(2019) = \sum_{n=0}^{1008}F_{2n+1}p_n(2019) = \sum_{n=0}^{1008}(-1)^n\binom{1009}nF_{2n+1} $$  Using Binet's Formula,
\begin{align*}
p(2019) &= \sum_{n=0}^{1008}(-1)^n\binom{1009}n\frac{\phi^{2n+1} - \left(-\frac1{\phi}\right)^{2n+1}}{\sqrt5} 
&= \frac1{\sqrt5}\left[\phi\sum_{n=0}^{1008}\binom{1009}n(-\phi^2)^n + \frac1{\phi}\sum_{n=0}^{1008}\binom{1009}n\left(-\frac1{\phi^2}\right)^n\right] 
&= \frac1{\sqrt5}\left[\phi\left[(1-\phi^2)^{1009} + \phi^{2018}\right] + \frac1{\phi}\left[\left(1-\frac1{\phi^2}\right)^{1009} + \frac1{\phi^{2018}}\right]\right] 
&= \frac1{\sqrt5}\left[\phi\left[(-\phi)^{1009} + \phi^{2018}\right] + \frac1{\phi}\left[\left(\frac1{\phi}\right)^{1009} + \frac1{\phi^{2018}}\right]\right] 
&= \frac1{\sqrt5}\left[-\phi^{1010} + \phi^{2019} + \frac1{\phi^{1010}} + \frac1{\phi^{2019}}\right] 
&= \frac{\phi^{2019} - \left(-\frac1{\phi}\right)^{2019}}{\sqrt5} - \frac{\phi^{1010} - \left(-\frac1{\phi}\right)^{1010}}{\sqrt5} 
&= F_{2019} - F_{1010}
\end{align*}
and so we have  $j=2019, k=1010$ .  $\blacksquare$

