draw((25 -5* 13 / 2, -60 + 12 * 13 / 2)--(25 + (12 - 5) * 13 / 2, -60 + (12 + 5) * 13 / 2));
draw((144 + (-12 + 5) * 13 / 2, 229 + (-12 - 5) * 13 / 2)--(144 + 5 * 13 / 2, 229 - 12  * 13 / 2));
draw((40, -40) -- (40 + 12 * 13, -40 + 5 * 13) -- (40 + 12 * 13 -  5 * 13, -40 + 5 * 13 + 12 * 13) -- (40 - 5 * 13, -40 + 12 * 13) -- cycle, blue);
dot((40 + 7 * 13 / 2, -40 + 19 * 13 / 2), blue);
